Rules.InvariantScript:
Set(_cmpNavSelID, 0);
// ORDER MATTERS. ClearCollect(colDetFields, ...) must run AFTER
// locDetKey is assigned. It previously ran before, so on a first visit
// every LookUp inside it resolved against a blank key and every field
// came back blank. It only looked correct because a context variable
// survives between visits, so the second and later visits used the
// PREVIOUS request's key.
//
// The UpdateContext below DECLARES both keys on this screen. A context
// variable is only recognised on a screen that sets it; arriving by
// Navigate does not declare it, and reading an undeclared one fails with
// "Name isn't valid", which reads like a typo.
//
// The fallback reads nfActiveRequests, a named formula over the LIST. It was
// First(colRequests), and the comment here used to explain that a named
// formula cannot reference a collection built in App.OnStart because named
// formulas evaluate first. True, and no longer relevant: the fallback no
// longer needs a collection at all, so the constraint dissolved rather than
// being worked around.
//
// CONSEQUENCE: the screen renders blank when SELECTED in the editor,
// because OnVisible only fires on preview or navigation. That is
// STRUCTURAL, not a defect. Press F5 to test.
//
// The fallback is also a production safeguard: a stale link to a
// soft-deleted request renders the first available request rather than a
// blank screen. If v1 needs a not-found state, this is the line to change.
UpdateContext(
    {
        locRequestKey: Coalesce(locRequestKey, Param("RequestKey"), First(nfActiveRequests).RequestKey),
        locDetKey: Coalesce(locRequestKey, Param("RequestKey"), First(nfActiveRequests).RequestKey),
        locDetTab: "routing",
        locDetActionsOpen: false,
        locDetConfirmOpen: false,
        locDetConfirmKind: "",
        locDetEmailBusy: false,
        locDetEmailFailed: false,
        locDetConfBusy: false,
        locDetRerouteOpen: false,
        locDetRerouteKey: "",
        locDetFinishOpen: false,
        locDetFinishKey: "",
        locDetBusy: false,
        locDetLoading: true,
        locDetSaveBusy: false,
        locWfOpen: false,
        locWfExpanded: 0}
);
// ONE UpdateContext, AND THE COALESCE IS WRITTEN TWICE ON PURPOSE.
//
// This was two calls: the first assigned locRequestKey, the second read
// it to assign locDetKey. colRequests had 2 rows, so
// First(colRequests).RequestKey was never blank, yet locDetKey came out
// blank. The only way that happens is the second statement reading
// locRequestKey as it was at the START of the formula rather than as the
// first statement had just left it. A context variable written and then
// read inside the same behaviour chain is not reliable.
//
// Both keys now derive from the same expression instead of one deriving
// from the other, so there is no ordering dependency left to get wrong.
// Inside a single UpdateContext record every right hand side sees the
// PRE-UPDATE values, which is exactly what is wanted here: locRequestKey
// on the right is the value passed in by Navigate, or blank.
//
// Do not "simplify" this by pointing locDetKey at locRequestKey. That is
// the bug.
// colDetFields is the ONE source for the 34 request fields. The rail
// summary and the Request Details tab are two renderings of it, so a new
// field is added here and shows up in both. A collection rather than a
// named formula because it depends on locDetKey, and named formulas have
// no screen scope.
// REQUEST SCOPED CHILD LOADS. Each delegates on RequestKey, which is indexed,
// and returns ONE request's rows rather than the head of the whole list. These
// replace reads of colRequests, colPhases and colAssignments, which are global
// loads TRUNCATED by the data row limit: a request whose children fell outside
// that window rendered an empty Routing tab, an empty Audit trail and a blank
// title, with no error anywhere to say so.
//
// These MUST run after the UpdateContext above, for the same reason colDetFields
// does: locDetKey has no value before it.
//
// Scoped NAMES rather than rebuilding the shared collections, because collections
// are app-global in Canvas and scrAllRequests reads colPhases for its preview
// panel. Rebuilding it here would corrupt that screen instead.
ClearCollect(colDetReq,    Filter(colRequests,           RequestKey = locDetKey));
ClearCollect(colDetPhases, Sort(Filter(colPhases, RequestKey = locDetKey), PhaseOrder));
ClearCollect(colDetAssign, Filter(colAssignments, RequestKey = locDetKey));

ClearCollect(
    colDetFields,
    With(
    { r: LookUp(colRequests, RequestKey = locDetKey) },
    With(
    { d: ParseJSON(r.DetailsJson) },
    Table(
    { Section: "Overview", FieldLabel: "Description",        FieldValue: Text(d.Description) },
    { Section: "Overview", FieldLabel: "Category",           FieldValue: LookUp(nfCategories, ConfigKey = r.CategoryKey).Title },
    { Section: "Overview", FieldLabel: "Processing",         FieldValue: LookUp(nfProcessingTypes, ConfigKey = r.ProcessingKey).Title },
    { Section: "Overview", FieldLabel: "Priority",           FieldValue: r.PriorityKey },
    { Section: "Overview", FieldLabel: "Status",             FieldValue: LookUp(nfStatusTable, StatusKey = r.StatusKey).Title },
    { Section: "Overview", FieldLabel: "Reference",          FieldValue: Text(d.ReferenceNumber) },
    { Section: "Contacts", FieldLabel: "Primary contact",    FieldValue: r.PrimaryPocName },
    { Section: "Contacts", FieldLabel: "Primary email",      FieldValue: r.PrimaryPocEmail },
    { Section: "Contacts", FieldLabel: "Secondary contact",  FieldValue: Text(d.SecondaryContact) },
    { Section: "Contacts", FieldLabel: "Secondary email",    FieldValue: Text(d.SecondaryEmail) },
    { Section: "Contacts", FieldLabel: "Request admins",     FieldValue: r.RequestAdmins },
    { Section: "Contacts", FieldLabel: "Parties of interest",FieldValue: Text(d.PartiesOfInterest) },
    { Section: "Org",      FieldLabel: "Department",         FieldValue: LookUp(nfDepartments, ConfigKey = r.DepartmentCode).Title },
    { Section: "Org",      FieldLabel: "Department name",    FieldValue: Text(d.DepartmentName) },
    { Section: "Org",      FieldLabel: "Teams",              FieldValue: Text(d.Teams) },
    { Section: "Org",      FieldLabel: "Approval level",     FieldValue: Text(d.ApprovalLevel) },
    { Section: "Dates",    FieldLabel: "Created",            FieldValue: nfDay(r.Created) },
    { Section: "Dates",    FieldLabel: "Last modified",      FieldValue: nfDay(r.Modified) },
    { Section: "Dates",    FieldLabel: "Due",                FieldValue: nfDay(r.RequestDueDate) },
    { Section: "Dates",    FieldLabel: "Requested by",       FieldValue: nfDay(DateValue(Text(d.DateRequestedBy))) },
    { Section: "Dates",    FieldLabel: "Approved deadline",  FieldValue: nfDay(r.ApprovedDeadline) },
    { Section: "Dates",    FieldLabel: "Extension",          FieldValue: If(IsBlank(Text(d.ExtensionDate)), "None", nfDay(DateValue(Text(d.ExtensionDate)))) },
    { Section: "Dates",    FieldLabel: "Completed",          FieldValue: If(IsBlank(r.CompletedDate), "Not completed", nfDay(r.CompletedDate)) },
    { Section: "Finance",  FieldLabel: "Budget",             FieldValue: nfMoney(r.BudgetAmount) },
    { Section: "Finance",  FieldLabel: "Cost centre",        FieldValue: r.CostCenter },
    { Section: "Finance",  FieldLabel: "Fiscal year",        FieldValue: r.FiscalYear },
    { Section: "Finance",  FieldLabel: "Funding source",     FieldValue: r.FundingSource },
    { Section: "Finance",  FieldLabel: "Project code",       FieldValue: Text(d.ProjectCode) },
    { Section: "Document", FieldLabel: "Document type",      FieldValue: Text(d.DocumentType) },
    { Section: "Document", FieldLabel: "Version",            FieldValue: Text(d.DocVersion) },
    { Section: "Document", FieldLabel: "Classification",     FieldValue: r.Classification },
    { Section: "Document", FieldLabel: "Links",              FieldValue: Text(d.Links) },
    { Section: "Document", FieldLabel: "Restricted",         FieldValue: If(Boolean(d.Restricted), "Yes", "No") },
    { Section: "Document", FieldLabel: "Expedited",          FieldValue: If(Boolean(d.Expedited), "Yes", "No") }
    )
    )
    )
);

ClearCollect(
            colDetAudit,
            ForAll(
                Sort(
                    Filter(colAudit, RequestKey = locDetKey),
                    EntryStamp,
                    SortOrder.Descending
                ) As a,
                {
                    EventTitle: Coalesce(
                        a.Title,
                        Switch(
                            a.ActionKey,
                            "email", "Email Sent",
                            "document", "Document Activity",
                            "task", "Task Activity",
                            "status", "Status Changed",
                            "phase", "Phase Activity",
                            "created", "Request Created",
                            "Activity"
                        )
                    ),
                    EventDescription: Coalesce(a.Detail, ""),
                    Author: Coalesce(a.ActorName, "System"),
                    DisplayDateTime: If(
                        DateValue(Text(a.EntryStamp, "mm/dd/yyyy")) = Today(),
                        "Today " & Text(a.EntryStamp, "h:mm AM/PM"),
                        nfDay(a.EntryStamp) & " " & Text(a.EntryStamp, "h:mm AM/PM")
                    ),
                    Category: Switch(
                        a.ActionKey,
                        "email", "Emails",
                        "document", "Documents",
                        "task", "Tasks",
                        "status", "Status Changes",
                        "phase", "Phases",
                        "System Events"
                    ),
                    HasSubDetail: a.ActionKey = "email" && !IsBlank(a.Meta),
                    SubTo: If(
                        a.ActionKey = "email" && !IsBlank(a.Meta),
                        Text(ParseJSON(a.Meta).to),
                        ""
                    ),
                    SubCC: If(
                        a.ActionKey = "email" && !IsBlank(a.Meta),
                        Text(ParseJSON(a.Meta).cc),
                        ""
                    ),
                    SubPriority: If(
                        a.ActionKey = "email" && !IsBlank(a.Meta),
                        Text(ParseJSON(a.Meta).priority),
                        ""
                    ),
                    SubMessage: If(
                        a.ActionKey = "email" && !IsBlank(a.Meta),
                        Left(Text(ParseJSON(a.Meta).message), 600),
                        ""
                    )
                }
            )
        );
        // ADAPTER FROM RequestAudit TO cmpActivityTimeline. Source is the seven
        // column contract: Title, RequestKey, ActionKey, ActorName, Detail,
        // EntryStamp, Meta. The component reads a fixed ten column shape, so
        // this ForAll is the seam and the only place the audit schema is
        // touched. Category must match a Value in FilterOptions and a Category
        // in IconMap on cmpDetAudit.
        //
        // META KEYS ARE THE ONE REMAINING GUESS: to, cc, priority, message,
        // camelCase to match DefinitionJson. If the envelope uses different
        // names, those four ParseJSON reads are the whole fix. A wrong key
        // returns Blank() with no error, so the symptom is an email card whose
        // envelope rows are empty rather than anything that fails loudly.
        //
        // Every Meta read is gated on ActionKey = "email". Meta carries a SECOND
        // shape for send back keys, and that shape has none of these fields.
        // Without the gate a send back row renders an empty email envelope.
        //
        // Meta is also gated on IsBlank. ParseJSON on an empty string errors and
        // Meta is optional.
        //
        // Category never falls through to blank. A blank Category matches no
        // filter and the row would vanish from every view including All
        // Activities, so "created" and anything unmapped land in System Events.
        //
        // Detail is NOT capped. It is a Note and a long comment is legitimately
        // shown in full. SubMessage IS capped at 600 per the component's own
        // guidance to bound long values at the source.
        //
        // DELEGATION: RequestKey is the ONLY indexed column on RequestAudit, so
        // the App.OnStart seed must filter on it server side. An audit trail is
        // the list most likely to pass 2000 rows first, since entries accumulate
        // forever and are never deleted.




        ClearCollect(
            colDetOpen,
            ForAll(
                Distinct(colDetFields, Section) As d,
                { SectionKey: d.Value }
            )
        );
        Select(btnDetFieldsRebuild_1);

        Reset(tabDetTabs);
        UpdateContext({ locDetLoading: false })
        // EVERY SECTION OPEN ON ARRIVAL for Request Details. A detail tab that
        // starts fully collapsed makes the user work to see anything, and the
        // whole point of that tab is that the sidebar shows eight fields and it
        // shows all 34.
        //
        // SMART DEFAULT ON ROUTING, which is different on purpose. Only the in
        // progress phase opens. A uniform default is wrong in both directions:
        // all closed makes the user hunt for the one thing they came for, all
        // open is unusable once a request has a dozen phases. If nothing is
        // InProgress every phase starts closed and the summary line on each
        // header still says what happened.
        //
        // BOTH COLLECTIONS MUST BE SEEDED HERE rather than inside their rebuild
        // buttons, because each rebuild READS its open set. Seeding inside would
        // make first render depend on the order of two statements, which is the
        // exact trap that left locDetKey blank.
        //
        // colRouteOpen holds phase AND comment expansion, separated by Kind.

Select(btnDetFinishApply);
IfError(
    UpdateContext(
        {
            locDetFinishRes:
                { ok: true, code: "ok", message: "", requeststatus: "" }
        }
    ),
    UpdateContext(
        {
            locDetFinishRes:
                {
                    ok: false,
                    code: "unreachable",
                    message: "Could not reach the workflow. " & FirstError.Message,
                    requeststatus: ""
                }
        }
    )
);
If(
    locDetFinishRes.code = "notactive" || locDetFinishRes.code = "unreachable",

    // Nothing was written. Drop the overlay and leave the dialog open so the
    // typed comment survives.
    UpdateContext({ locDetBusy: false });
    Notify(locDetFinishRes.message, NotificationType.Warning),

    // REQUEST SCOPED, both of them. These read the WHOLE list once,
    // which silently refilled two request-scoped collections with the
    // truncated head of every request's rows. It was masked only because
    // the Navigate below re-runs OnVisible and rebuilds them correctly,
    // so the bug was one removed line away from returning.
    //
    // Refresh FIRST, for the same reason as the reroute branch below:
    // CompleteAssignment writes SERVER SIDE and the client-side cache of
    // these lists does not notice, so a re-read can return the old rows.
    ClearCollect(
        colDetAssign,
        Filter(colAssignments, RequestKey = locDetKey)
    );
    ClearCollect(
        colDetPhases,
        Sort(Filter(colPhases, RequestKey = locDetKey), PhaseOrder)
    );
    ClearCollect(
        colAudit,
        ShowColumns(
            colAudit,
            RequestKey, Title, ActionKey, ActorName, Detail,
            EntryStamp, Meta
        )
    );
    ClearCollect(
        colDetReq,
        Filter(colRequests, RequestKey = locDetKey)
    );
    UpdateContext(
        {
            locDetFinishOpen: false,
            locDetFinishKey: "",
            locDetBusy: false
        }
    );
    Reset(cmpDetFinish_1);
    Navigate(scrDetails, ScreenTransition.None, { locRequestKey: locDetKey })
)

IfError(
    UpdateContext(
        {
            locDetSaveRes:
                { ok: false, code: "unreachable", message: "Saving would update the request fields and log the change to the audit trail. " & nfGateSuffix, requeststatus: "" }
        }
    ),
    UpdateContext(
        {
            locDetSaveRes:
                {
                    ok: false,
                    code: "unreachable",
                    message: "Could not reach the workflow. " & FirstError.Message,
                    created: "0", updated: "0", deleted: "0", skipped: "0"
                }
        }
    )
);
If(
    !locDetSaveRes.ok,
    UpdateContext({ locDetSaveBusy: false });
    Notify(locDetSaveRes.message, NotificationType.Warning),
    UpdateContext({ locDetSaveBusy: false, locWfOpen: false });
    Notify(locDetSaveRes.message, NotificationType.Success);
    Reset(cmpDetWorkflow);
    Navigate(scrDetails, ScreenTransition.None, { locRequestKey: locDetKey })
)
// IfError ASSIGNS locDetSaveRes ON BOTH BRANCHES, so the test below can
// never depend on which one ran. Branching on a busy flag instead is what
// made the previous version skip its whole reload.
//
// NOT CLOSED WHEN ok IS FALSE. "emptyworkflow" comes back having changed
// nothing and the draft is the only copy of the edit, so the dialog stays
// open and populated and just warns.
//
// THE RELOAD IS A Navigate, not a hand written re-read, and that is the
// point. OnVisible rebuilds colDetReq, colDetPhases, colDetAssign,
// colDetFields, colDetAudit, colDetOpen and colRouteOpen and fires both
// rebuild buttons. tmrDetReroute and tmrDetConfirm already end this way.
// It also means the Audit tab shows the row this flow just wrote, which a
// hand written re-read on this screen has never done.
//
// Refresh BEFORE the Navigate: the writes were SERVER SIDE and the client
// cache does not notice, so OnVisible would rebuild from stale rows.

IfError(
    UpdateContext(
        {
            locDetRrRes:
                { ok: false, code: "unreachable", message: "Rerouting would reassign this task and log the change to the audit trail. " & nfGateSuffix, requeststatus: "" }
        }
    ),
    UpdateContext(
        {
            locDetRrRes:
                {
                    ok: false,
                    code: "unreachable",
                    message: "Could not reach the workflow. " & FirstError.Message,
                    assignee: ""
                }
        }
    )
);
If(
    !locDetRrRes.ok,

    // NOTHING WAS WRITTEN on notfound, alreadydone, nochange or unreachable.
    // Drop the overlay and leave the dialog open so the typed reason survives.
    UpdateContext({ locDetRrBusy: false });
    Notify(locDetRrRes.message, NotificationType.Warning),

    // The flow moved the task. Reload the two collections a reroute can
    // change, request scoped, then navigate so OnVisible rebuilds the rest.
    ClearCollect(
        colDetAssign,
        Filter(colAssignments, RequestKey = locDetKey)
    );
    UpdateContext(
        {
            locDetRerouteOpen: false,
            locDetRerouteKey: "",
            locDetRrBusy: false
        }
    );
    // Refresh BEFORE re-reading. The write happened server side, so the
    // ClearCollect above would otherwise be answered from the client cache,
    // which still holds the previous assignee.
    Reset(cmpDetReroute_1);
    Navigate(scrDetails, ScreenTransition.None, { locRequestKey: locDetKey })
)

IfError(
    UpdateContext(
        {
            locDetConfRes:
                If(
                    Coalesce(locDetConfirmKind, "suspend") = "delete"
                    || Coalesce(locDetConfirmKind, "suspend") = "restore",
                    { ok: false, code: "unreachable", message: "This would change the request status and log the change to the audit trail. " & nfGateSuffix, requeststatus: "" },
                    { ok: false, code: "unreachable", message: "This would change the request status and log the change to the audit trail. " & nfGateSuffix, requeststatus: "" }
                )
        }
    ),
    UpdateContext(
        {
            locDetConfRes:
                {
                    ok: false,
                    code: "unreachable",
                    message: "Could not reach the workflow. " & FirstError.Message,
                    requeststatus: ""
                }
        }
    )
);
If(
    !locDetConfRes.ok,
    UpdateContext({ locDetConfBusy: false });
    Notify(locDetConfRes.message, NotificationType.Warning),

    UpdateContext({ locDetConfBusy: false });
    Notify(locDetConfRes.message, NotificationType.Success);
    If(
        Coalesce(locDetConfirmKind, "suspend") = "delete",
        Navigate(scrAllRequests, ScreenTransition.None),
        Navigate(scrDetails, ScreenTransition.None, { locRequestKey: locDetKey })
    )
)
// BOTH FLOWS RETURN THE SAME FOUR FIELDS, which is why one If can choose
// between them and one branch can read the result. DeleteRequest returns a
// blank requeststatus; nothing here reads it.
//
// DELETE NAVIGATES AWAY. The request no longer passes IsDeleted = false, and
// this screen's OnVisible fallback resolves a blank key to the FIRST active
// request, so staying would quietly show somebody else's request and look
// like the delete hit the wrong row.
//
// Refresh before the Navigate: the writes were SERVER SIDE and the client
// cache does not notice, so OnVisible would rebuild from stale rows.

Table(
    { id: "home", label: "Home" },
    { id: "request", label: locDetKey }
)

With(
    {
        t: Coalesce(CountRows(cmpProgressRail.ResolvedSteps), 0),
        d: Coalesce(CountRows(Filter(cmpProgressRail.ResolvedSteps, CountsAsDone)), 0)
    },
    RoundDown(d / Max(t, 1) * 100, 0)
)

ForAll(
    Sort(cmpProgressRail.Steps, Order) As s,
    With(
        {
            hit: Filter(
                cmpProgressRail.StateMap,
                Lower(State) = Lower(Coalesce(s.State, ""))
            )
        },
        With(
            {
                m: If(
                    CountRows(hit) > 0,
                    First(hit),
                    LookUp(cmpProgressRail.StateMap, Lower(State) = "default")
                )
            },
            {
                Order: s.Order,
                Title: s.Title,
                State: s.State,
                Label: If(IsBlank(s.Detail), m.Label, s.Detail),
                NodeColor: m.NodeColor,
                TrackColor: m.TrackColor,
                TrackFill: m.TrackFill,
                Emphasize: m.Emphasize,
                CountsAsDone: m.CountsAsDone,
                IsCurrent: m.IsCurrent
            }
        )
    )
)

Table(
    { Order: 1, Title: "Submitted", State: "done",     Detail: "" },
    { Order: 2, Title: "Review",    State: "current",  Detail: "" },
    { Order: 3, Title: "Approval",  State: "upcoming", Detail: "" }
)

With(
    {
        s: LookUp(colDetReq, RequestKey = locDetKey).StatusKey,
        cur: Coalesce(
            LookUp(
                colDetPhases,
                RequestKey = locDetKey && PhaseStatusKey = "InProgress"
            ).Title,
            ""
        )
    },
    Switch(
        s,
        "NotStarted", "Not started",
        "Completed", "All phases complete",
        "OnHold",
            If(IsBlank(cur), "On hold", "On hold at " & cur),
        If(IsBlank(cur), "In progress", "Current: " & cur)
    )
)

ForAll(
    Sort(
        Filter(colDetPhases, RequestKey = locDetKey),
        PhaseOrder
    ) As p,
    {
        Order: p.PhaseOrder,
        Title: p.Title,
        State: p.PhaseStatusKey,
        Detail: ""
    }
)
// The ForAll is a COLUMN RENAME, not a state translation. The
// component takes Order, Title, State, Detail and colDetPhases
// carries PhaseOrder, Title, PhaseStatusKey. PhaseStatusKey goes
// through untouched, because StateMap above keys off the same
// four values the contract fixes. Keys never labels holds: no
// label is written into a filter or a comparison anywhere here.
//
// DELEGATION: colDetPhases is in memory, so this predicate is
// local and cannot hit a limit. It is loaded in OnVisible from
// 'RequestPhases' filtered on THIS request, delegated on the
// indexed RequestKey, so it holds one request's phases in full.
//
// It used to read colPhases, a GLOBAL load of the whole list
// truncated by the data row limit. The predicate was local then
// too, which is why this comment read as reassuring while the
// rail rendered empty for any request outside the fetched head.
// A local predicate over an incomplete collection is exactly as
// wrong as a non-delegable one, and says nothing at all.

With(
    {
        t: Coalesce(CountRows(cmpProgressRail.ResolvedSteps), 0),
        d: Coalesce(CountRows(Filter(cmpProgressRail.ResolvedSteps, CountsAsDone)), 0)
    },
    RoundDown(d / Max(t, 1) * 100, 0)
)

ForAll(
    Sort(cmpProgressRail.Steps, Order) As s,
    With(
        {
            hit: Filter(
                cmpProgressRail.StateMap,
                Lower(State) = Lower(Coalesce(s.State, ""))
            )
        },
        With(
            {
                m: If(
                    CountRows(hit) > 0,
                    First(hit),
                    LookUp(cmpProgressRail.StateMap, Lower(State) = "default")
                )
            },
            {
                Order: s.Order,
                Title: s.Title,
                State: s.State,
                Label: If(IsBlank(s.Detail), m.Label, s.Detail),
                NodeColor: m.NodeColor,
                TrackColor: m.TrackColor,
                TrackFill: m.TrackFill,
                Emphasize: m.Emphasize,
                CountsAsDone: m.CountsAsDone,
                IsCurrent: m.IsCurrent
            }
        )
    )
)

Rule.InvariantScript:
With(
    {
        mainMin:
            If(conDetCurrent.Visible, conDetCurrent.Height + nfSpace.Lg, 0)
            + tabDetTabs.Height
            + nfSpace.Lg
            + lblDetTabMinH.Height
    },
    If(
        nfIsDesktop,
        Max(conDetSidebar.Height, mainMin),
        conDetSidebar.Height + mainMin + Self.LayoutGap
    )
)
// Reads lblDetTabMinH.Height, the single carrier.
//
// On desktop this resolves to Max(sidebar, mainMin) and the sidebar
// wins at about 560 whenever a tab needs less than that. That is why
// every floor under 14 rows had no visible effect: the Switch was
// being computed and then discarded by the Max.
//
// nfSpace.Lg above is conDetMain.LayoutGap, restated because Self
// here is the split. It is the only duplication left.

If(conDetCurrent.Visible, conDetCurrent.Height + Self.LayoutGap, 0)
+ tabDetTabs.Height
+ Self.LayoutGap
+ lblDetTabMinH.Height
// The split reserves the room from the gutter, this reserves it
// from the split, and conDetTabBody claims it. All three read
// the same carrier, so they cannot silently disagree.

Rules.InvariantScript:
CountRows(
    Filter(colDetAssign, RequestKey = locDetKey, StatusKey = "InProgress")
)
* If(
    nfIsDesktop,
    nfSize.RowLg + nfSpace.Md,
    nfSize.RowLg + nfSize.RowSm + nfSpace.Xxl + nfSpace.Md
)
// WAS Self.AllItemsCount * Self.TemplateHeight, WHICH IS CIRCULAR.
// AllItemsCount is how many rows the gallery has actually loaded,
// and that depends on how tall the gallery is. It happens to
// settle correctly here, but the same expression collapsed a
// gallery to 4px inside cmpFileUpload. Counting the source and
// restating TemplateSize removes the cycle. Keep the multiplier
// in step with TemplateSize below.

UpdateContext(
    {
        locDetFinishOpen: true,
        locDetFinishKey: ThisItem.AssignmentKey}
)
// Opens the Complete Task overlay only. The overlay writes nothing.
// Its submit is the marked call site, per CLAUDE.md Flows.

UpdateContext(
    {
        locDetRerouteOpen: true,
        locDetRerouteKey: ThisItem.AssignmentKey}
