                RequestKey: locDetKey,
                PhaseKey: prev.PhaseKey,
                AssignmentKey: locDetKey & "-A" & CountRows(colAssignments) + 1,
                AssignmentOrder:
                    Max(
                        Filter(colAssignments, RequestKey = locDetKey, PhaseKey = prev.PhaseKey),
                        AssignmentOrder
                    ),
                AssigneeName:
                    LookUp(
                        Sort(
                            Filter(colAssignments, RequestKey = locDetKey, PhaseKey = prev.PhaseKey),
                            AssignmentOrder,
                            SortOrder.Descending
                        ),
                        true
                    ).AssigneeName,
                AssigneeEmail:
                    LookUp(
                        Sort(
                            Filter(colAssignments, RequestKey = locDetKey, PhaseKey = prev.PhaseKey),
                            AssignmentOrder,
                            SortOrder.Descending
                        ),
                        true
                    ).AssigneeEmail,
                DepartmentCode: me.DepartmentCode,
                Goal: "Sent back: " & cmpDetFinish_1.Comment,
                Required: true,
                DurationDays: 2,
                IsGroup: false,
                GroupId: Blank(),
                StatusKey: "NotStarted",
                RerouteReturnTo: me.AssignmentKey
            }
        );
        Patch(
            colAssignments,
            LookUp(colAssignments, AssignmentKey = me.AssignmentKey),
            {
                StatusKey: "NotStarted",
                OutcomeKey: Blank(),
                CompletedDate: Blank()
            }
        );
        Patch(
            colPhases,
            LookUp(colPhases, PhaseKey = prev.PhaseKey),
            { PhaseStatusKey: "InProgress" }
        )
    ),
    Select(btnDetAdvance)
);
If(
    !IsBlank(LookUp(colAssignments, AssignmentKey = locDetFinishKey).RerouteReturnTo)
        && cmpDetFinish_1.OutcomeKey = "Approve",
    Patch(
        colAssignments,
        LookUp(
            colAssignments,
            AssignmentKey = LookUp(colAssignments, AssignmentKey = locDetFinishKey).RerouteReturnTo
        ),
        { StatusKey: "NotStarted" }
    );
    Select(btnDetAdvance)
)
// THE LOCAL FINISH. This is the free build; the paid build replaces the
// whole handler with one CompleteAssignment.Run and keeps the dialog
// untouched.
//
// THE ASSIGNMENT IS WRITTEN FIRST AND UNCONDITIONALLY, because it
// happened regardless of what the outcome then triggers. Comments is the
// real column name; CompletionComment does not exist and reading it was
// silently blank for weeks.
//
// ActedByEmail RECORDS WHO ACTUALLY PRESSED IT, which is not always the
// assignee: a group assignment can be completed by any member, and
// without this the audit says the group did it.
//
// APPROVE FALLS THROUGH TO THE ADVANCE and does nothing else. Whether
// this completes an order, a phase or the whole request is not decided
// here; btnDetAdvance derives all of it from the rows.
//
// REJECT HOLDS THE PHASE AND THE REQUEST and does NOT advance. The
// routing panel tints the whole band from PhaseStatusKey, so holding
// only the request would leave a phase that still looks live.
//
// SEND BACK CREATES A NEW ASSIGNMENT rather than reopening an old one,
// so the previous round stays in the record. It lands at the LAST order
// of the previous phase, addressed to whoever held that last order, and
// carries RerouteReturnTo pointing at the assignment that sent it back.
// The sender's own row goes back to NotStarted so the walk finds it
// again later.
//
// THE RETURN POINTER IS HONOURED AT THE END: completing an assignment
// that carries RerouteReturnTo reopens its target, and the advance then
// resumes exactly where the send back came from instead of walking the
// previous phase forward again.
//
// SEND BACK FROM PHASE ONE IS IMPOSSIBLE. There is no previous phase and
// prev comes back blank. The dialog must disable the option, which is
// the guard that actually prevents it; this handler assumes it was.

ClearCollect(
    colWfRowsTmp,
    ForAll(
        Filter(colWfDraftPhases, !IsRemoved) As p,
        {
            RowType: "phase",
            SortPhase: p.PhaseOrder,
            SortRow: 0,
            PhaseClientId: p.ClientId,
            RowClientId: p.ClientId,
            Title: p.Title,
            Subtitle: p.PhaseGoal,
            StatusKey: p.PhaseStatusKey,
            IsLocked: p.IsLocked,
            IsExpanded: p.ClientId = locWfExpanded,
            WorkerCount: CountRows(Filter(colWfDraftWorkers, PhaseClientId = p.ClientId, !IsRemoved)),
            AssignmentOrder: 0,
            DepartmentCode: "",
            Required: false,
            DurationDays: 0,
            IsGroup: false,
            AssigneeEmail: "",
            GroupId: ""
        }
    )
);
If(
    locWfExpanded > 0,
    Collect(
        colWfRowsTmp,
        ForAll(
            Sort(Filter(colWfDraftWorkers, PhaseClientId = locWfExpanded, !IsRemoved), AssignmentOrder) As w,
            {
                RowType: "worker",
                SortPhase: LookUp(colWfDraftPhases, ClientId = locWfExpanded).PhaseOrder,
                SortRow: w.AssignmentOrder,
                PhaseClientId: w.PhaseClientId,
                RowClientId: w.ClientId,
                Title: w.AssigneeName,
                Subtitle: w.Goal,
                StatusKey: w.StatusKey,
                IsLocked: LookUp(colWfDraftPhases, ClientId = locWfExpanded).IsLocked,
                IsExpanded: false,
                WorkerCount: 0,
                AssignmentOrder: w.AssignmentOrder,
                DepartmentCode: w.DepartmentCode,
                Required: w.Required,
                DurationDays: w.DurationDays,
                IsGroup: w.IsGroup,
                AssigneeEmail: w.AssigneeEmail,
                GroupId: w.GroupId
            }
        )
    );
    If(
        !LookUp(colWfDraftPhases, ClientId = locWfExpanded).IsLocked,
        Collect(
        colWfRowsTmp,
        {
            RowType: "add",
            SortPhase: LookUp(colWfDraftPhases, ClientId = locWfExpanded).PhaseOrder,
            SortRow: 9999,
            PhaseClientId: locWfExpanded,
            RowClientId: 0,
            Title: "",
            Subtitle: "",
            StatusKey: "",
            IsLocked: false,
            IsExpanded: false,
            WorkerCount: 0,
            AssignmentOrder: 0,
            DepartmentCode: "",
            Required: false,
            DurationDays: 0,
            IsGroup: false,
            AssigneeEmail: "",
            GroupId: ""
        }
        )
    )
);
ClearCollect(
    colWfRows,
    SortByColumns(colWfRowsTmp, "SortPhase", SortOrder.Ascending, "SortRow", SortOrder.Ascending)
)
// HIDDEN REBUILD. Called with Select(btnDetWfRebuild) at the end of
// every draft mutation. It lives in one control rather than being
// pasted into a dozen OnSelect handlers, and it is a control rather
// than a behaviour UDF so it can read locWfExpanded, which a UDF in
// App.Formulas has no screen scope to see.
//
// The two step collect through colWfRowsTmp is required: a
// ClearCollect whose source reads the collection it is clearing has
// undefined behaviour.
//
// A locked phase never contributes worker rows, which is how the
// read only rule for a Completed phase lives in the data rather
// than in a dozen Visible formulas.

Table(
  {Label: "Cancel", ButtonType: "Secondary", Action: "Cancel", Visible: true}, 
  {Label: "Confirm", ButtonType: "Primary", Action: "Confirm", Visible: true}
)

"<div style='
    display:block;
    width:" & Self.Width & "px;
    height:" & Self.Height - 1 & "px;
    background:" & cmpEnhancedDialog.OverlayBlurColor & ";
    backdrop-filter: blur(6px);
'></div>"

Table(
    { Label: "Cancel", ButtonType: "Secondary", Action: "Cancel", Visible: true },
    {
        Label:
            Switch(
                Coalesce(locDetConfirmKind, "suspend"),
                "suspend", "Suspend workflow",
                "resume",  "Resume workflow",
                "restart", "Restart from the beginning",
                "restore", "Restore request",
                "Delete request"
            ),
        ButtonType: "Primary",
        Action: "Go",
        Visible: true
    }
)
// THE PRIMARY LABEL SAYS WHAT HAPPENS, never "Confirm". Restart discards
// completed work and Delete removes the request from every view; a button
// reading "Confirm" on either is how someone presses it without reading.

If(
    Coalesce(locDetConfirmKind, "suspend") = "restart"
    || Coalesce(locDetConfirmKind, "suspend") = "delete",
    "Danger",
    If(Coalesce(locDetConfirmKind, "suspend") = "restore", "Success", "Warning")
)
// Restore is the only one of the five that UNDOES something, so it is the
// only one that is not a warning. Danger stays reserved for the two that
// destroy: restart discards completed work, delete hides the request.

true
// A REASON IS MANDATORY on all four. Every one of these changes state with
// nobody having done the work, so the audit row is the only record of why it
// happened. The component enforces it: with DialogType "Form" the Primary
// button is disabled while the input is blank, so there is nothing to
// validate here and no way to confirm without saying why.

If(
    Self.SelectedButton.Action <> "Cancel",
    UpdateContext(
        {
            locDetConfBusy: true
        }
    )
);
UpdateContext({ locDetConfirmOpen: false })
// Self, NOT cmpDetConfirm. On an instance the control is Self; naming the
// component resolves to nothing and the handler silently never fires.
//
// The flow call is in tmrDetConfirm. Calling it here would run before the
// overlay paints, so the screen would freeze with no feedback.

"<div style='
    display:block;
    width:" & Self.Width & "px;
    height:" & (Self.Height - 1) & "px;
    background:rgba(0,0,0," & cmpLoadingSpinner.OverlayOpacity & ");
    " & If(cmpLoadingSpinner.ShowBlur, "backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);", "") & "
'></div>"

Clear(colDetFieldRows);
ForAll(
    Distinct(colDetFields, Section) As s,
    Collect(
        colDetFieldRows,
        {
            RowType: "section",
            Section: s.Value,
            FieldLabel: "",
            FieldValue: "",
            IsOpen: !IsBlank(LookUp(colDetOpen, SectionKey = s.Value)),
            FieldCount: CountRows(Filter(colDetFields, Section = s.Value))
        }
    );
    If(
        !IsBlank(LookUp(colDetOpen, SectionKey = s.Value)),
        Collect(
            colDetFieldRows,
            ForAll(
                Filter(colDetFields, Section = s.Value) As f,
                {
                    RowType: "field",
                    Section: f.Section,
                    FieldLabel: f.FieldLabel,
                    FieldValue: f.FieldValue,
                    IsOpen: false,
                    FieldCount: 0
                }
            )
        )
    )
)
// FLAT ROW PROJECTION, because Canvas galleries CANNOT NEST. A
// section gallery containing a field gallery is not expressible, so
// sections and fields share one gallery and RowType decides which
// template shows. Same shape as colWfRows in Edit Workflow.
//
// ForAll is used here as a BEHAVIOUR function, iterating sections in
// order and appending as it goes, so the interleaving falls out of
// execution order and no sort column is needed. The alternative was
// two tables plus a SortSec and SortRow pair, which is what Edit
// Workflow needed only because its rows come from two different
// collections.
//
// SECTION ORDER FOLLOWS Distinct(colDetFields, Section), which is
// first appearance in colDetFields. Reordering the rows in the
// OnVisible literal reorders the sections here. There is no second
// ordering contract to keep in step, which is deliberate.
//
// A COLLAPSED SECTION CONTRIBUTES NO FIELD ROWS AT ALL, rather than
// rows with Visible false. A gallery still lays out invisible rows,
// so hiding 30 of 34 fields would leave 30 rows of empty space.

With(
    {
        colW: Min(
            conDetRight.Width - If(nfIsMobile, 2 * nfSpace.Lg, 2 * nfSpace.Xxl),
            nfPageMaxW
        )
    },
    conDetRoot.PaddingLeft
    + (conDetRight.Width - colW) / 2
    + colW
    - nfSpace.Lg
    - Self.Width
)

With(
    {
        _items: If(Coalesce(LookUp(colDetReq, RequestKey = locDetKey).IsDeleted, false), 1, 4)
    },
    _items * nfSize.Row
    + (_items - 1) * Self.LayoutGap
    + Self.PaddingTop
    + Self.PaddingBottom
)
// FOUR VISIBLE ITEMS: Edit Workflow, one of Suspend or Resume, Restart,
// Delete. Suspend and Resume are exact complements on request status, so
// exactly one of the five children is ever hidden.
//
// THIS COUNT IS THE THING TO CHANGE when a menu item is added, and it is
// the thing that was missed: the literal said 3 from when the menu held
// Edit Workflow, Suspend and Delete. Adding two items left it at 3, and
// an AutoLayout container CLIPS what does not fit rather than growing or
// erroring, so Delete simply stopped being on screen. Nothing failed and
// nothing warned.
//
// A container cannot count its own visible children here: they are
// declared after it, and a parent reading a later sibling is a forward
// reference that palint reports as PAL037 and Studio drops on paste.

UpdateContext({ locDetActionsOpen: false });
ClearCollect(
    colWfDraftPhases,
    ForAll(
        Sort(Filter(colDetPhases, RequestKey = locDetKey), PhaseOrder) As p,
        {
            ClientId: p.PhaseOrder,
            PhaseKey: p.PhaseKey,
            Title: p.Title,
            PhaseOrder: p.PhaseOrder,
            PhaseGoal: p.PhaseGoal,
            PhaseStatusKey: p.PhaseStatusKey,
            IsLocked: p.PhaseStatusKey = "Completed",
            IsNew: false,
            IsRemoved: false
        }
    )
);
ClearCollect(
    colWfDraftWorkers,
    ForAll(
        Sort(Filter(colDetAssign, RequestKey = locDetKey), AssignmentOrder) As a,
        {
            ClientId: 1000 + a.ID,
            PhaseClientId: LookUp(colDetPhases, PhaseKey = a.PhaseKey).PhaseOrder,
            AssignmentKey: a.AssignmentKey,
            AssignmentOrder: a.AssignmentOrder,
            AssigneeName: a.AssigneeName,
            AssigneeEmail: a.AssigneeEmail,
            DepartmentCode: a.DepartmentCode,
            Goal: a.Goal,
            Required: a.Required,
            DurationDays: a.DurationDays,
            IsGroup: a.IsGroup,
            GroupId: a.GroupId,
            StatusKey: a.StatusKey,
            IsNew: false,
            IsRemoved: false
        }
    )
);
UpdateContext(
    {
        locWfOpen: true,
        locWfExpanded: Coalesce(
            First(Filter(colWfDraftPhases, PhaseStatusKey = "InProgress")).ClientId,
            First(Filter(colWfDraftPhases, !IsLocked)).ClientId
        )}
);
Select(btnDetWfRebuild)
// Opens the Edit Workflow overlay and seeds the DRAFT only.
// Nothing here writes a list or calls a flow. Save is the one
// marked call site, at the foot of the panel.

UpdateContext(
    {
        locDetActionsOpen: false,
        locDetConfirmKind: "suspend",
        locDetConfirmOpen: true
    }
)

UpdateContext(
    {
        locDetActionsOpen: false,
        locDetConfirmKind: "resume",
        locDetConfirmOpen: true
    }
)

UpdateContext(
    {
        locDetActionsOpen: false,
        locDetConfirmKind: "restart",
        locDetConfirmOpen: true
    }
)

UpdateContext(
    {
        locDetActionsOpen: false,
        locDetConfirmKind: If(Coalesce(LookUp(colDetReq, RequestKey = locDetKey).IsDeleted, false), "restore", "delete"),
        locDetConfirmOpen: true
    }
)
// The comment this replaces said delete is "cascaded by Flow".
// It is not, and it cannot be: no child list has an IsDeleted
